//! Blanket implementations of [`Callable`] for `Fn` closures and function
//! pointers of arities 0 through 12.
//!
//! The upper bound of 12 is dictated by the standard library: `Fn` is
//! implemented for tuples up to 12 elements, and no higher arity exists on
//! stable Rust.
//!
//! The implementations are generated by the `gen_impl_callable!` macro from
//! `closed-proc-macros`.

use crate::traits::Callable;

closed_proc_macros::gen_impl_callable!(12);
